from threetears.evals import Eval

from service import handle


def desk(case):
    """Answer one request at the holds desk."""
    return handle(case["request"])


def flags_expired(case, out):
    """The holds flagged expired are exactly the ones past their pickup date."""
    return sorted(hold.id for hold in out.holds if hold.expired) == case["expired"]


holds = Eval("tests/fixtures/requests.jsonl", runner=desk, grader=[flags_expired], k=1)
